window.ScripturaLexicons.BDAG_PART_0143 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitereo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτηρέω epitēréō verbo vigiar atentamente; ficar à espreita BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτηρέω</td><td>verbo</td><td>vigiar atentamente; ficar à espreita</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitithemi-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτίθημι epitíthēmi verbo; ativo e médio colocar sobre; impor; conferir; acrescentar; atacar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτίθημι</td><td>verbo; ativo e médio</td><td>colocar sobre; impor; conferir; acrescentar; atacar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitimao-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτιμάω epitimáō verbo repreender; censurar; advertir; punir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτιμάω</td><td>verbo</td><td>repreender; censurar; advertir; punir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitimia-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτιμία, ας, ἡ epitimía substantivo feminino punição; castigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτιμία, ας, ἡ</td><td>substantivo feminino</td><td>punição; castigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitoauto-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτοαυτό epitoautó locução; remissão ver ἐπί, 1cβ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτοαυτό</td><td>locução; remissão</td><td>ver ἐπί, 1cβ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitrepo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτρέπω epitrépō verbo; ativo e passivo permitir; autorizar; confiar; ordenar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτρέπω</td><td>verbo; ativo e passivo</td><td>permitir; autorizar; confiar; ordenar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitropeuo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτροπεύω epitropeúō verbo exercer a função de procurador; administrar como representante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτροπεύω</td><td>verbo</td><td>exercer a função de procurador; administrar como representante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitrope-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτροπή, ῆς, ἡ epitropḗ substantivo feminino autorização; incumbência; comissão; plenos poderes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτροπή, ῆς, ἡ</td><td>substantivo feminino</td><td>autorização; incumbência; comissão; plenos poderes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitropos-bdag\" data-source=\"BDAG\" data-search=\"ἐπίτροπος, ου, ὁ epítropos substantivo masculino administrador; intendente; mordomo; tutor; guardião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίτροπος, ου, ὁ</td><td>substantivo masculino</td><td>administrador; intendente; mordomo; tutor; guardião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitropos-person-bdag\" data-source=\"BDAG\" data-search=\"Ἐπίτροπος, ου, ὁ Epítropos nome próprio masculino Epítropo; nome pessoal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἐπίτροπος, ου, ὁ</td><td>nome próprio masculino</td><td>Epítropo; nome pessoal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epitynchano-bdag\" data-source=\"BDAG\" data-search=\"ἐπιτυγχάνω epitynchánō verbo alcançar; obter; conseguir; atingir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιτυγχάνω</td><td>verbo</td><td>alcançar; obter; conseguir; atingir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphaino-bdag\" data-source=\"BDAG\" data-search=\"ἐπιφαίνω epiphaínō verbo; ativo e passivo mostrar; iluminar; manifestar-se; aparecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιφαίνω</td><td>verbo; ativo e passivo</td><td>mostrar; iluminar; manifestar-se; aparecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphaneia-bdag\" data-source=\"BDAG\" data-search=\"ἐπιφάνεια, ας, ἡ epipháneia substantivo feminino aparição; manifestação; manifestação gloriosa; aspecto exterior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιφάνεια, ας, ἡ</td><td>substantivo feminino</td><td>aparição; manifestação; manifestação gloriosa; aspecto exterior</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphan-e-ios-bdag\" data-source=\"BDAG\" data-search=\"Ἐπιφάν(ε)ιος, ου Epiphán(e)ios nome próprio masculino Epifânio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἐπιφάν(ε)ιος, ου</td><td>nome próprio masculino</td><td>Epifânio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphanes-bdag\" data-source=\"BDAG\" data-search=\"ἐπιφανής, ές epiphanḗs adjetivo esplêndido; glorioso; notável; resplandecente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιφανής, ές</td><td>adjetivo</td><td>esplêndido; glorioso; notável; resplandecente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphausko-bdag\" data-source=\"BDAG\" data-search=\"ἐπιφαύσκω epiphaúskō verbo resplandecer sobre; nascer; aparecer; iluminar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιφαύσκω</td><td>verbo</td><td>resplandecer sobre; nascer; aparecer; iluminar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphero-bdag\" data-source=\"BDAG\" data-search=\"ἐπιφέρω epiphérō verbo; ativo e médio trazer; conceder; infligir; acrescentar; acusar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιφέρω</td><td>verbo; ativo e médio</td><td>trazer; conceder; infligir; acrescentar; acusar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphrasso-bdag\" data-source=\"BDAG\" data-search=\"ἐπιφράσσω epiphrássō verbo fechar; tapar; obstruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιφράσσω</td><td>verbo</td><td>fechar; tapar; obstruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphoneo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιφωνέω epiphōnéō verbo gritar; clamar em voz alta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιφωνέω</td><td>verbo</td><td>gritar; clamar em voz alta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epiphosko-bdag\" data-source=\"BDAG\" data-search=\"ἐπιφώσκω epiphṓskō verbo amanhecer; raiar; começar a clarear; aproximar-se o dia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιφώσκω</td><td>verbo</td><td>amanhecer; raiar; começar a clarear; aproximar-se o dia</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-epitereo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτηρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitēréō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">τηρέω</span>; Hinos Homéricos, Tucídides e outros; inscrições [Sb 8304, 8], papiros; Jt 13:3.) <b>Ficar atento a, vigiar cuidadosamente, ficar à espreita de</b>, B 10:4.</p></section></article>\n<article id=\"entry-epitithemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτίθημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitíthēmi⟧</span><span class=\"separator\">·</span><span>verbo; ativo e médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Terceira pessoa plural <span class=\"greek\">ἐπιτιθέασιν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:4</a>; imperativo <span class=\"greek\">ἐπιτίθει</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5:22</a>; imperfeito, terceira pessoa plural <span class=\"greek\">ἐπετίθεσαν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:17</a> (variante de leitura <span class=\"greek\">ἐπετίθουν</span>); futuro <span class=\"greek\">ἐπιθήσω</span>; primeiro aoristo <span class=\"greek\">ἐπέθηκα</span>; segundo aoristo <span class=\"greek\">ἐπέθην</span>, imperativo <span class=\"greek\">ἐπίθες</span>, particípio <span class=\"greek\">ἐπιθείς</span>. Voz média: futuro <span class=\"greek\">ἐπιθήσομαι</span>; segundo aoristo <span class=\"greek\">ἐπεθέμην</span> (ver <span class=\"greek\">τίθημι</span>; desde Homero).</p>\n<p class=\"entry-text\"><b>① Colocar algo sobre algum lugar ou objeto, transferindo-o para ele.</b></p>\n<p class=\"entry-text\"><b>ⓐ Pôr, colocar sobre.</b></p>\n<p class=\"entry-text\"><b><span class=\"greek\">α</span>. Literalmente</b>, no ativo, acerca de colocar um objeto físico: <span class=\"greek\">τὶ</span> (por vezes subentendido pelo contexto; cf. Est 5:2) <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> ou <span class=\"greek\">τινα</span>, <i>pôr alguma coisa sobre algo ou alguém</i> (Xen., Cyr. 7, 3, 14; SIG 1173, 9; cf. 1169, 4; PSI 442, 13 [séc. III a.C.]; Gn 22:9; 42:26 e outros; JosAs 29:5: <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἵππον</span>; ParJer 2:1: <span class=\"greek\">χοῦν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:5</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:6</a>, variante de leitura (a maioria dos manuscritos traz <span class=\"greek\">ἐπέχρισεν</span>); 9:15; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:10</a>; 28:3; B 7:8.</p>\n<p class=\"entry-text\"><span class=\"greek\">χεῖρα</span> (<span class=\"greek\">χεῖρας</span>) <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> ou <span class=\"greek\">τι</span>, <i>impor a mão (as mãos) sobre alguém ou alguma coisa</i> (SIG 1173, 4; Êx 29:10; Lv 1:4; 4:4 e outros; K. Sudhoff, «Handanlegg. des Heilgottes», <i>Archiv f. Gesch. d. Med.</i> 18 [1926], pp. 235–250), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:18</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:25</a> (variante <span class=\"greek\">ἔθηκεν</span>); 16:18; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:17</a>; 9:17 (cf. 1QapGen e S. Kotlek, ANRW II, Principat 37/3, p. 2859). Também <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> (Jos., Ant. 9, 268; 16, 365), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:13</a>, 15; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:23</a>; 6:5; 8:23; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:40</a>; 13:13 (variante <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτῇ</span>); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 6:6</a>; 8:19; 9:12; 13:3; 19:6; 28:8 (ver <span class=\"greek\">χείρ</span>, final [Coppens]). Quanto à autorização como presbítero, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5:22</a> (Goodspeed, <i>Problems</i>, pp. 181s.; cf. 1QapGen 20, 29); cf. <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:32</a>; AcPl Ha 3, 31; 4, 34; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span>, B 13:5 (Gn 48:18). Ver <span class=\"greek\">ἐπίθεσις</span>.</p>\n<p class=\"entry-text\">Em outras combinações, <span class=\"greek\">ἐ</span>. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> (Xen., Oec. 17, 9; Est 2:17; 1 Esdr 4:30; TestJob 7:1; JosAs 10:5; Jos., Ant. 9, 149: <span class=\"greek\">ἐπέθεσαν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στέφανον</span>): <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σταυρόν</span>, <i>puseram-lhe a cruz</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:26</a>; <span class=\"greek\">στέφανον</span> … <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κεφαλῇ</span>, <i>uma coroa … sobre sua cabeça</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:2</a>; <span class=\"greek\">ἐπειθήσι</span> (= <span class=\"greek\">ἐπιθήσει</span>) <span class=\"greek\">σοι</span> <span class=\"greek\">ἐλευθέριον</span> <span class=\"greek\">στέφανον</span>, <i>ele te imporá uma coroa de liberdade</i>, AcPl Ha 2, 31; <span class=\"greek\">τοὺς</span> <span class=\"greek\">λίθους</span> <span class=\"greek\">ἐπετίθουν</span> <span class=\"greek\">ἀλλήλαις</span>, <i>colocavam as pedras umas sobre os ombros das outras</i>, Hs 9, 3, 5.</p>\n<p class=\"entry-text\"><span class=\"greek\">τὶ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span> (Heródoto 1, 121, 4 e outros; 1 Km 6:18; Sus 34; ParJer 5:7; Just., D. 132, 2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:16</a>, variante de leitura; <span class=\"greek\">ἐπέθηκαν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">αὐτοῦ</span>, <i>puseram-na (a coroa de espinhos) sobre a cabeça dele</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:29</a>; <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κεφαλῆς</span>, <i>colocar acima da cabeça dele</i>, versículo 37. <span class=\"greek\">τῷ</span> <span class=\"greek\">μνημείῳ</span> <span class=\"greek\">λίθον</span>, <i>uma pedra junto ao túmulo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:53</a>, variante; (<span class=\"greek\">λίθοι</span>) <span class=\"greek\">ἐπιτιθέμενοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκοδομήν</span>, <i>(pedras) assentadas na construção</i>, Hv 3, 5, 2.</p>\n<p class=\"entry-text\"><b><span class=\"greek\">β</span>. Figurado</b>, no ativo (exceto <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:28</a>, abaixo): <span class=\"greek\">ἐ</span>. <span class=\"greek\">πληγάς</span> <span class=\"greek\">τινι</span>, <i>infligir golpes a alguém</i> (BGU 759, 13 [séc. II d.C.]: <span class=\"greek\">πληγὰς</span> <span class=\"greek\">πλείστας</span> <span class=\"greek\">ἐπέθηκάν</span> <span class=\"greek\">μοι</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:23</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:30</a>. Diferentemente, <span class=\"greek\">ἐπιθήσει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πληγάς</span>, <i>Deus trará sobre ele as pragas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22:18</a>b (cf. <span class=\"greek\">δίκην</span> <span class=\"greek\">τινί</span>, Heródoto, Platão e outros; UPZ 1, 13 [séc. IV a.C.]: <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δίκην</span> <span class=\"greek\">ἐ</span>.; Dt 26:6; <span class=\"greek\">τειμωρίαν</span> <span class=\"greek\">τινί</span>, IAndrosIsis, Cime 20; 35); ver B. Olsson, «D. Epilog der Offb. Joh.», ZNW 31 (1932), pp. 84–86. Passivo em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:28</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐ</span>. <span class=\"greek\">τινὶ</span> <span class=\"greek\">ὄνομα</span>, <i>dar um sobrenome a alguém</i> (Heródoto 5, 68 e outros; BGU 1139, 7 [séc. I a.C.]; 2 Esdr 19:7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:16</a>s. (quanto à atribuição de novos nomes aos discípulos, cf. Diógenes Laércio 5, 38: Teofrasto chamava-se <span class=\"greek\">Τύρταμος</span>; seu mestre Aristóteles o renomeou [<span class=\"greek\">μετωνόμασεν</span>] Teofrasto por sua eloquência quase divina). Em B 12:8s.; <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔλεος</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, <i>conceder misericórdia a alguém</i>, B 15:2.</p>\n<p class=\"entry-text\"><b>ⓑ Dar alguma coisa a alguém</b>, <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, voz média (BGU 1208 I, 4 [27 a.C.]; PRyl 81, 9: <span class=\"greek\">τὴν</span> <span class=\"greek\">ὅλου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πράγματος</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κατασπορεῦσι</span> <span class=\"greek\">ἐπεθέμην</span>): <span class=\"greek\">ἀναγομένοις</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χρείας</span>, <i>quando partimos por mar, eles nos deram o necessário</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:10</a>; a menos que o verbo deva ser traduzido por <i>colocar a bordo os suprimentos necessários</i> (assim NRSV, REB).</p>\n<p class=\"entry-text\"><b>ⓒ Acrescentar</b>, com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, voz ativa (Homero e outros): <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτά</span>, <i>a essas coisas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22:18</a>a.</p>\n<p class=\"entry-text\"><b>② Arremeter contra alguém: atacar, pôr-lhe as mãos.</b> Voz média (Jos., Ant. 1, 328), com <span class=\"greek\">τινί</span> (Heródoto, Aristófanes e outros; Apiano, Liby. 102 §482; PTebt 15, 11 [114 a.C.]; PFlor 332, 7; LXX; Fílon, Leg. ad Gai. 371; Jos., Ant. 4, 96), seguida de infinitivo substantivado de finalidade no genitivo (Gn 43:18): <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἐπιθήσεταί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κακῶσαί</span> <span class=\"greek\">σε</span>, <i>ninguém te atacará para te fazer mal</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:10</a>. — M-M; TW.</p></section></article>\n<article id=\"entry-epitimao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτιμάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitimáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito, terceira pessoa singular <span class=\"greek\">ἐπετίμα</span>, terceira pessoa plural <span class=\"greek\">ἐπετίμων</span>; futuro, segunda pessoa plural <span class=\"greek\">ἐπιτιμήσετε</span>, Rt 2:16; primeiro aoristo <span class=\"greek\">ἐπετίμησα</span>; particípio passivo <span class=\"greek\">ἐπιτιμηθείς</span>, 3 Mac 2:24; cf. Just., D. 116, 13 sobre Zc 3:2 (ver <span class=\"greek\">τιμάω</span>; Heródoto [-<span class=\"greek\">έω</span>], Tucídides, Platão e posteriores).</p>\n<p class=\"entry-text\"><b>① Manifestar forte desaprovação a alguém: repreender, censurar, reprovar.</b> Também <b>falar seriamente, advertir</b> para impedir uma ação ou fazer cessar uma conduta. Em uso absoluto (Tucídides 4, 28, 1; Demóstenes 1, 16 e outros; SIG 344, 55 [?]; Sir 11:7; Jos., Ant. 5, 105), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:41</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:2</a>.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">τινί</span> (Xen., Platão; Epicteto 3, 22, 10 e outros; Luciano, Dial. Mort. 1, 8; PMagd 24, 5 [218 a.C.]; UPZ 64, 7; Gn 37:10 e outros; Fílon, De Jos. 74; Jos., C. Ap. 2, 239): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:26</a>; 17:18; 19:13; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:39</a> (cf. Sl 105:9); 8:32s.; 10:13; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:39</a>; 8:24; 9:21, 42, 55; 17:3; 18:15; 19:39; 23:40.</p>\n<p class=\"entry-text\">Seguido de <span class=\"greek\">ἵνα</span> ou <span class=\"greek\">ἵνα</span> <span class=\"greek\">μή</span>, para introduzir aquilo que a censura ou advertência procura ocasionar ou impedir: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:16</a>; 16:20, variante (por <span class=\"greek\">διαστέλλω</span>, ver esse verbete); 20:31; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:12</a> (quanto a <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἐπετίμα</span>, cf. Ps.-Xenofonte, Cyn. 12, 16); 8:30 (sobre <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:12</a> e 8:30, ver G. Barton, JBL 41 [1922], pp. 233–236); 10:48; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:39</a>.</p>\n<p class=\"entry-text\">Seguido de <span class=\"greek\">λέγων</span> e discurso direto: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:22</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:25</a>; 9:25 (sobre a terminologia do exorcismo em Marcos, ver H. Kee, NTS 14 [1968], pp. 232–246); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:35</a>. Em Jd 9, <span class=\"greek\">ἐ</span>. pode equivaler a <i>repreender</i>, em contraste com <i>difamar</i>, algo evitado pelo arcanjo (sobre o passivo, cf. AssMos, fragmento j [Denis, p. 67]; ver J. Tromp, <i>The Assumption of Moses</i> [1993], pp. 272s.); mas a acepção seguinte também é provável nessa passagem.</p>\n<p class=\"entry-text\"><b>② Punir.</b> (Diod. S. 3, 67, 2: <span class=\"greek\">πληγαῖς</span> <span class=\"greek\">ἐπιτιμηθείς</span>; 3 Mac 2:24; En 98:5; ParJer 6:17; Jos., Ant. 18, 107.) — DELG, s.v. <span class=\"greek\">τιμή</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epitimia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτιμία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitimía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Demóstenes e outros; Fílon; em Jos., C. Ap. 2, 199, <span class=\"greek\">ἐπιτίμιον</span>.) <b>Punição, castigo</b> (assim OGI 669, 43 [séc. I d.C.]; PLond I, 77, 53, p. 234 [séc. VIII d.C.]; Sb 3:10; Ath. 1, 4), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 2:6</a>. — DELG, s.v. <span class=\"greek\">τιμή</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epitoauto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτοαυτό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitoautó⟧</span><span class=\"separator\">·</span><span>locução; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Remissão:</b> <span class=\"greek\">ἐπιτοαυτό</span>; ver <span class=\"greek\">ἐπί</span>, acepção 1c<span class=\"greek\">β</span>.</p></section></article>\n<article id=\"entry-epitrepo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτρέπω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitrépō⟧</span><span class=\"separator\">·</span><span>verbo; ativo e passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέτρεψα</span>. Passivo: infinitivo futuro <span class=\"greek\">ἐπιτραπήσεσθαι</span> (Just., A I, 47, 5); segundo aoristo passivo <span class=\"greek\">ἐπετράπην</span>; perfeito <span class=\"greek\">ἐπιτέτραμμαι</span> (de <span class=\"greek\">τρέπω</span>, «voltar ou dirigir para»; desde Homero).</p>\n<p class=\"entry-text\"><b>① Permitir que alguém faça alguma coisa: permitir, autorizar.</b> (Assim Píndaro e outros.) Com <span class=\"greek\">τινί</span>, <i>a alguém</i>, seguido de infinitivo (Xen., An. 1, 2, 19; Hell. 6, 3, 9; Epicteto 1, 10, 10; 2, 7, 12; PMagd 2, 7 [221 a.C.]; 12, 11; PRyl 120, 16; Jó 32:14; 4 Mac 4:18; ParJer 1:4; Jos., Ant. 8, 202; Just., Ath.): <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:21</a>; 19:8; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:32</a>a; 9:59, 61; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:39</a>; 27:3; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 2:12</a>; Dg 10:2; IEph 10:1; IRo 6:3; Hm 4, 1, 4; D 10:7; Ox 840, 12.</p>\n<p class=\"entry-text\">Sem infinitivo (Píndaro, O. 3, 36; SIG 260, 16; 360, 15; 34; Just., D. 141, 2; Taciano 20, 1; Atenágoras 1, 2; 2, 4): <span class=\"greek\">ἐπέτρεψεν</span> <span class=\"greek\">αὐτοῖς</span>, <i>deu-lhes permissão</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:13</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:32</a>b; <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἐπιτρέψῃ</span>, <i>àquele a quem ele próprio permite</i> = <i>designa</i>, ISm 8:1; <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐμαυτῷ</span> <span class=\"greek\">ἐπιτρέψας</span>, <i>não por iniciativa própria</i>, Pol 3:1.</p>\n<p class=\"entry-text\">Em uso absoluto (Píndaro, O. 6, 21; Xen., Cyr. 5, 5, 9; SIG 490, 10; 591, 36): <span class=\"greek\">ἐπέτρεψεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Πιλᾶτος</span>, <i>Pilatos deu permissão</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:38</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:40</a>; MPol 7:2. Sobre Deus (BGU 451, 10 [séculos I/II d.C.]: <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἐπιτρεπόντων</span>; BGU 248, 15 [cf. Deissmann, NB 80 = BS 252]; Jos., Ant. 20, 267: <span class=\"greek\">κἂν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">ἐπιτρέπῃ</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 16:7</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:3</a>.</p>\n<p class=\"entry-text\">Passivo (SIG 1073, 44; 52; POxy 474, 40): <span class=\"greek\">ἐπιτρέπεταί</span> <span class=\"greek\">τινι</span>, <i>permite-se a alguém</i>, seguido de infinitivo (Jos., Ant. 5, 3), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:1</a>; 28:16; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 14:34</a>. Em uso absoluto: <span class=\"greek\">ἐκείνῳ</span> <span class=\"greek\">ἐπιτέτραπται</span>, <i>a tarefa lhe foi confiada</i> = <i>é seu dever</i>, Hv 2, 4, 3.</p>\n<p class=\"entry-text\"><b>② Ordenar, instruir.</b> (Xen., An. 6, 5, 11; Arriano, Ind. 23, 5: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τινί</span>; Cássio Dio, fragmento 40, 5 Boiss. Cod.; PLond 1173, 3; Jos., Vi. 138.) Com dativo de pessoa e infinitivo, 1 Cl 1:3. — B. 1340. Frequentemente como variante de leitura de <span class=\"greek\">ἐπιστρέφω</span>. — M-M.</p></section></article>\n<article id=\"entry-epitropeuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτροπεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitropeúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete seguinte e <span class=\"greek\">ἐπιτρέπω</span>; desde Heródoto; inscrições, papiros, Fílon; Jos., Bell. 7, 9; Ant. 10, 278; Atenágoras 25, 1.) <b>Exercer o cargo de um <span class=\"greek\">ἐπίτροπος</span>: atuar como procurador.</b> (Plut., Mor. 471a; IG XIV, 911.) Com <span class=\"greek\">τινός</span>, <i>de um território</i> (Heródoto 3, 15): <span class=\"greek\">ἐπιτροπεύοντος</span> <span class=\"greek\">Ποντίου</span> <span class=\"greek\">Πιλάτου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰουδαίας</span>, <i>quando Pôncio Pilatos exercia a procuradoria da Judeia</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:1</a>, códice D (em lugar de <span class=\"greek\">ἡγεμονεύοντος</span>). O termo empregado pelo códice D é historicamente inexato, pois Pilatos era <b>prefeito</b>; ver <span class=\"greek\">ἐπίτροπος</span> e cf. <span class=\"greek\">ἡγεμονεύω</span>. — Mason, s.v. <span class=\"greek\">ἐπίτροπος</span>; DELG, s.v. <span class=\"greek\">τρέπω</span>; M-M.</p></section></article>\n<article id=\"entry-epitrope-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτροπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitropḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Tucídides e outros; inscrições, papiros, 2 Mac 13:14.) <b>Autorização para executar uma tarefa: permissão, incumbência, comissão, plenos poderes.</b> (Políbio 3, 15, 7; Diod. S. 17, 47, 4; Dionísio de Halicarnasso 2, 45; POxy 743, 32 [2 a.C.]: <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπιτροπὴν</span> <span class=\"greek\">δέδωκα</span>; Fílon, Poster. Cai. 181; Jos., Ant. 8, 162; Just., A I, 29, 2.) <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐπιτροπῆς</span>, <i>com autorização</i> (junto de <span class=\"greek\">ἐξουσία</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:12</a>. — M-M; Sv.</p></section></article>\n<article id=\"entry-epitropos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίτροπος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epítropos⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Píndaro, Heródoto e outros; inscrições, papiros, LXX; ParJer 4:5; Fílon, Josefo, Justino; empréstimo no hebraico rabínico.) Designação aplicada a diferentes funcionários e agentes.</p>\n<p class=\"entry-text\"><b>① Administrador, encarregado, intendente, mordomo.</b> (Heródoto e outros; Fílon, Omn. Prob. Lib. 35; Jos., Ant. 7, 369), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:8</a>. Também <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:3</a> (Jos., Ant. 18, 194), acerca de Cuza, alto funcionário do séquito de Herodes, talvez responsável pela administração de seus bens. A palavra também é usada para governadores e procuradores (Heródoto e outros; Jos., Ant. 15, 406 e outros; cf. índice de OGI VIII; Magie, pp. 162s.; Hahn, pp. 118; 224, nota 2; Rouffiac, p. 46; Preisigke, <i>Fachwörter</i>, p. 93), mas Cuza possuía status político inferior.</p>\n<p class=\"entry-text\"><b>② Tutor, guardião.</b> (Heródoto 9, 10; Tucídides 2, 80, 6; Diod. S. 11, 79, 6; SIG 364, 53; 1014, 122 e outros; POxy 265, 28; PRyl 109, 18; 2 Mac 11:1; 13:2; 14:2; Fílon, Somn. 1, 107), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:2</a>. — O. Eger, ZNW 18 (1918), pp. 105–108; S. Belkin, JBL 54 (1935), pp. 52–55; sobre o uso de <span class=\"greek\">ἐ</span>. no sentido de «tutor», ver FX 7 (1981), pp. 254s.; Betz, <i>Galatians</i>, p. 203. — Schürer I, pp. 357–360; Mason, p. 49; DELG, s.v. <span class=\"greek\">τρέπω</span>; M-M; TW.</p></section></article>\n<article id=\"entry-epitropos-person-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐπίτροπος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Epítropos⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Raro; SIG 957, 34.) <b>Epítropo</b>, homem cuja esposa é destinatária da saudação em IPol 8:2. Ver Hdb., ad loc.</p></section></article>\n<article id=\"entry-epitynchano-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιτυγχάνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epitynchánō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, terceira pessoa singular <span class=\"greek\">ἐπιτεύξεται</span>, Pv 12:27; segundo aoristo <span class=\"greek\">ἐπέτυχον</span> (ver <span class=\"greek\">τυγχάνω</span>; pré-socráticos, Heródoto e posteriores; inscrições, papiros, LXX, pseudoepígrafos; Jos., Ant. 5, 288; Fílon, Justino; Atenágoras, R. 57, 16 e outros). <b>Ser bem-sucedido em conseguir ou alcançar aquilo que se procura: obter, atingir, alcançar.</b></p>\n<p class=\"entry-text\">Com <b>genitivo do que é alcançado</b> (Aristófanes, Plut. 245; Tucídides 3, 3, 3; BGU 113, 3; 522, 8; Jos., Ant. 18, 279), de coisas (GrBar 4:13: <span class=\"greek\">ὀργῆς</span> <span class=\"greek\">θεοῦ</span>, <i>ira de Deus</i>; ApcEsdr 6:22: <span class=\"greek\">στεφάνου</span>, <i>coroa</i>; Apiano, Iber. 48 §200: <span class=\"greek\">εἰρήνης</span>, <i>paz</i>), Hm 10, 2, 4; 2 Cl 5:6; <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπαγγελίας</span>, <i>a promessa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:15</a>; cf. 11:33; <span class=\"greek\">τοῦ</span> <span class=\"greek\">κλήρου</span>, <i>a herança ou porção</i>, ITr 12:3; <span class=\"greek\">χάριτος</span>, <i>graça</i>, IRo 1:2a.</p>\n<p class=\"entry-text\"><span class=\"greek\">θεοῦ</span>, <b>alcançar Deus</b>, expressão especialmente inaciana para designar o martírio como via direta para Deus: IEph 12:2; IMg 14; ITr 12:2; 13:3; IRo 1:2; 2:1; 4:1; 9:2; ISm 11:1; IPol 2:3; 7:1. Também <span class=\"greek\">ἐ</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <i>alcançar Jesus Cristo</i>, IRo 5:3. Sem objeto expresso, IPhld 5:1.</p>\n<p class=\"entry-text\">Com <b>acusativo: obter</b> (Xen., Hell. 4, 5, 19; 4, 8, 21; 6, 3, 16; UPZ 41, 26 [161/160 a.C.]: <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἐπιτυγχάνειν</span>; TestSol 9:3: <span class=\"greek\">προδότην</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:7</a>; <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰτημάτων</span>, <i>nenhuma das coisas solicitadas</i>, Hm 9:5.</p>\n<p class=\"entry-text\">Seguido de infinitivo (Luciano, Necyom. 6; Jos., Bell. 1, 302; Justino), IRo 1:1. Em uso absoluto (Platão, Men. 97c; SIG 736, 79 [92 a.C.]), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:29</a>, códice D; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:2</a>; IEph 1:2; IRo 8:3. — M-M; Sv.</p></section></article>\n<article id=\"entry-epiphaino-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιφαίνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiphaínō⟧</span><span class=\"separator\">·</span><span>verbo; ativo e passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέφανα</span>, infinitivo <span class=\"greek\">ἐπιφᾶναι</span>, imperativo <span class=\"greek\">ἐπίφανον</span>; futuro médio <span class=\"greek\">ἐπιφανοῦμαι</span>, Jr 36:14. Passivo: futuro, terceira pessoa singular <span class=\"greek\">ἐπιφανήσεται</span>, Sf 2:11 (ver o verbete seguinte e <span class=\"greek\">φαίνω</span>; Teógnis, Heródoto e outros; inscrições, papiros, LXX, Fílon, Josefo).</p>\n<p class=\"entry-text\"><b>① Fazer com que algo seja visto: mostrar.</b> Ativo transitivo: <span class=\"greek\">ἐπίφανον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπόν</span> <span class=\"greek\">σου</span>, <i>faz resplandecer teu rosto</i>, 1 Cl 60:3 (Sl 79:4, 8, 20; Dn 9:17, Teodocião).</p>\n<p class=\"entry-text\"><b>② Proporcionar iluminação: dar luz a, iluminar.</b> Ativo, extensão da acepção ①, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.79\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:79</a>. Há uma pequena diferença entre esse uso aparentemente intransitivo e o seguinte, claramente transitivo. Sobre o tema da solicitude divina ao oferecer luz em meio às trevas, ver Xen., Mem. 4, 3, 4.</p>\n<p class=\"entry-text\"><b>③ Tornar perceptível a própria presença: aparecer, manifestar-se.</b> Ativo, extensão da acepção ① (Teócrito 2, 11, sobre astros; Políbio 5, 6, 6, sobre a luz do dia; Dt 33:2; Sl 117:27), acerca do sol e das estrelas, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:20</a>; cf. ②.</p>\n<p class=\"entry-text\"><b>④ Mostrar-se, fazer uma aparição.</b> Passivo (Heródoto, Tucídides e outros; LXX). Acerca de Deus (cf. Cáriton 1, 14, 1: <span class=\"greek\">Ἀφροδίτην</span> <span class=\"greek\">ἐπιφαίνεσθαι</span>; escólio a Apolônio de Rodes 2, introdução: <span class=\"greek\">ἐπεφάνη</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀπόλλων</span>; SIG 557, 6: <span class=\"greek\">ἐπιφαινομένης</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">Ἀρτέμιδος</span>; 1168, 26; Sb 6152, 5 [96 a.C.], sobre Ísis; 6153, 6; Gn 35:7; 2 Mac 3:30; 3 Mac 6:9; Fílon; Jos., Ant. 5, 277; 8, 240, 268): <span class=\"greek\">τοῖς</span> <span class=\"greek\">δεομένοις</span>, <i>aos necessitados</i>, 1 Cl 59:4. Acerca da graça de Deus, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:11</a>; do amor de Deus, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:4</a>. — M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-epiphaneia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιφάνεια, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epipháneia⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; pré-socráticos; Políbio e outros; inscrições, papiros [ver ②], LXX, ApcEsdr 3:3, p. 27, 7 Tdf.; EpArist, Fílon, Josefo, Justino.) Em geral, <b>aparecimento, aparição</b>, particularmente uma aparição esplêndida, por exemplo da rica cidade de Babilônia (Diod. S. 2, 11, 3).</p>\n<p class=\"entry-text\">Como termo técnico relacionado ao transcendente, designa <b>manifestação visível, muitas vezes repentina, de uma divindade oculta</b>, quer por sua presença pessoal, quer por um ato de poder ou comunicação oracular que torna conhecida sua presença (OGI 233, 35s. [sécs. III/II a.C.], Ártemis; Dionísio de Halicarnasso 2, 68; Diod. S. 1, 25, 3 e 4; 2, 47, 7 [aparição de Apolo]; 5, 49, 5, <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἐπιφάνεια</span>, para ajudar os seres humanos; Plut., Them. 127 [30, 3]; Élio Aristides 48, 45 K. = 24, p. 477 D.; Polieno 2, 31, 4: <span class=\"greek\">Διοσκούρων</span> <span class=\"greek\">ἐ</span>.; frequente em inscrições, e na LXX sobretudo em 2 e 3 Mac; Aristóbulo, em Eus., PE 8, 10, 3 [p. 136, 25 Holladay]; EpArist 264; Jos., Ant. 1, 255; 2, 339; 3, 310; 9, 60; 18, 75, 286).</p>\n<p class=\"entry-text\">Sobre os testemunhos e a bibliografia, ver F. Pfister, «Epiphanie», <i>Pauly-W.</i>, suplemento IV (1924), pp. 277–323; M. Dibelius, <i>Handbuch</i>, excursus sobre <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 1:10</a>; O. Casel, «D. Epiphanie im Lichte d. Religionsgesch.», <i>Benedikt. Monatsschr.</i> 4 (1922), pp. 13ss.; R. Herzog, <i>Die Wunderheilungen v. Epidauros</i> (1931), p. 49; B. Easton, <i>Pastoral Epistles</i> (1947), pp. 171s.; C. Westermann, <i>Das Loben Gottes in den Psalmen</i> (1954), p. 70; E. Schnutenhaus, «Das Kommen u. Erscheinen Gottes im AT», ZAW 76 (1964), pp. 1–21; E. Pax, <i><span class=\"greek\">Ἐπιφάνεια</span></i> (1955); D. Lührmann, <i>K. Kuhn Festschr.</i> (1971); RAC V, pp. 832–909. Em nossa literatura, exceto em Pápias, o vocábulo refere-se somente à manifestação de Cristo na terra.</p>\n<p class=\"entry-text\"><b>① Ato de aparecer: aparição.</b> Em nossa literatura, de Jesus.</p>\n<p class=\"entry-text\"><b>ⓐ Sua primeira manifestação na terra</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 1:10</a> (Just., A I, 14, 3 e outros; Diod. S. 3, 62, 10: os mitógrafos falam de duas manifestações de Dioniso, <span class=\"greek\">δευτέραν</span> <span class=\"greek\">ἐπιφάνειαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἀνθρώποις</span>). — A. Law, <i>Manifest in Flesh</i> (1996).</p>\n<p class=\"entry-text\"><b>ⓑ Sua manifestação no juízo</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 6:14</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:1</a>, 8. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">δόξης</span>, <i>manifestação da glória</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:13</a> (cf. para essa combinação OGI 763, 19s.; Epicteto 3, 22, 29). <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">παρουσίας</span>, <i>manifestação de sua vinda</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 2:8</a>; a combinação não é excessivamente redundante, pois <span class=\"greek\">ἐ</span>. designa a salvação que entra em vigor quando ocorre a <span class=\"greek\">παρουσία</span>. <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐ</span>., <i>o dia da manifestação</i>, 2 Cl 12:1; 17:4.</p>\n<p class=\"entry-text\"><b>② Aquilo que normalmente se pode ver: aparência superficial, aspecto exterior.</b> (Demócrito, Aristóteles e outros.) <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">βάθος</span> <span class=\"greek\">εἶχον</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἔξωθεν</span> <span class=\"greek\">ἐπιφανείας</span>, <i>os olhos (de Judas) ficavam tão profundamente situados atrás da pele (inchada) do rosto</i>, Pápias 3:2. Sobre o uso de <span class=\"greek\">ἐ</span>. na descrição de sintomas, ver E. Goodspeed, «A Medical Papyrus Fragment», AJP 24 (1903), p. 328, linha 5; cf. Galeno 16, p. 530. — DELG, s.v. <span class=\"greek\">φαίνω</span>; <i>New Docs</i> 4, pp. 80s.; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-epiphan-e-ios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐπιφάν(ε)ιος, ου</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Epiphán(e)ios⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Frequente desde o século IV d.C.; OGI 688, 1; papiros.) <b>Epifânio</b>, cristão em Corinto, AcPl Ha 6, 1.</p></section></article>\n<article id=\"entry-epiphanes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιφανής, ές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiphanḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os verbetes iniciados por <span class=\"greek\">ἐπιφ</span>-; Píndaro, Heródoto e posteriores; inscrições, papiros, LXX, Fílon; Jos., Ant. 4, 200 e outros; Just., A I, 68, 3 [superlativo].) <b>Relativo ao que resplandece: esplêndido, glorioso, notável, resplandecente.</b> Provavelmente sugere uma luz cujo impacto é especialmente marcante por seu aparecimento súbito. Sobre o dia do juízo de Deus (Mélanges G. Glotz [1932], p. 290, 28: inscrição [séc. II a.C.]: <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ἐ</span>.): <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐ</span>., <i>o dia do Senhor, grande e glorioso</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:20</a> (Jl 3:4). — <i>New Docs</i> 4, p. 148; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-epiphausko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιφαύσκω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiphaúskō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπιφαύσω</span> (Hesíquio = <span class=\"greek\">ἀνατέλλω</span>, <span class=\"greek\">φαίνω</span>; voz média em Jó 41:10). <b>Resplandecer sobre, erguer-se, aparecer, brilhar</b> (acerca dos astros: Jó 25:5; 31:26; quanto ao dia, Cássio Dio 9, 12, 8 e Act. Thom. 34 [Aa II/2, p. 151, 12]). Com <span class=\"greek\">τινί</span>, <i>para ou sobre alguém</i> (Orph. Hymn. 50, 9 Q., acerca de Baco: <span class=\"greek\">θνητοῖς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀθανάτοις</span> <span class=\"greek\">ἐπιφαύσκων</span>); acerca de Cristo: <span class=\"greek\">ἐπιφαύσει</span> <span class=\"greek\">σοι</span>, <i>Cristo resplandecerá sobre ti</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:14</a> (a variante <span class=\"greek\">ἐπιψαύσεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, que acompanha Crisóstomo, deve ser rejeitada). A origem da citação não foi estabelecida com segurança. — Reitzenstein, <i>Erlösungsmysterium</i>, pp. 6, 136; K. Kuhn, NTS 7 (1961), pp. 334–346 (Qumran). Ver ainda <span class=\"greek\">ἐπιφώσκω</span>. — Frisk, s.v. <span class=\"greek\">φάο</span>; cf. DELG, s.v. <span class=\"greek\">φάε</span>; TW.</p></section></article>\n<article id=\"entry-epiphero-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιφέρω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiphérō⟧</span><span class=\"separator\">·</span><span>verbo; ativo e médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐποίσω</span>, LXX; segundo aoristo <span class=\"greek\">ἐπήνεγκον</span>, infinitivo <span class=\"greek\">ἐπενεγκεῖν</span>; médio, terceira pessoa singular <span class=\"greek\">ἐπηνέγκατο</span> (Melitão, P. 51, 371); infinitivo perfeito <span class=\"greek\">ἐπενηνοχέναι</span> (Just., D. 60, 5); particípio aoristo passivo, genitivo singular <span class=\"greek\">ἐπενεχθέντος</span>, 2 Mac 12:35 (ver <span class=\"greek\">φέρω</span>; desde Homero).</p>\n<p class=\"entry-text\"><b>① Conceder alguma coisa a alguém: trazer, dar, outorgar.</b> Com acusativo da coisa e dativo da pessoa: <span class=\"greek\">μετανοίας</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ἐπήνεγκεν</span>, <i>concedeu a graça do arrependimento</i>, 1 Cl 7:4, variante de leitura.</p>\n<p class=\"entry-text\"><b>② Levar alguma coisa e colocá-la sobre alguém: pôr sobre, aplicar.</b> Com <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, acerca de objetos que foram postos em contato com o corpo de Paulo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:12</a>, variante de leitura.</p>\n<p class=\"entry-text\"><b>③ Fazer alguém ou alguma coisa sofrer uma adversidade: trazer sobre, causar, infligir.</b> Com <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> (EpArist 206: <span class=\"greek\">αἰσχύνην</span> <span class=\"greek\">ἀνθρώποις</span>; TestJob 7:13: <span class=\"greek\">ὑποστῆναι</span> <span class=\"greek\">ἅπερ</span> <span class=\"greek\">ἐπιφέρεις</span> <span class=\"greek\">μοι</span>; Fílon, Leg. ad Gai. 133). <span class=\"greek\">ἁμαρτίαν</span>, <i>pecado</i>, 1 Cl 47:4, variante; Hv 1, 2, 4; Hm 11:4. <span class=\"greek\">βλασφημίας</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span>, <i>injúrias ou difamações ao nome</i>, 1 Cl 47:7. A respeito de coisas que servem como castigo (EpArist 253: <span class=\"greek\">θάνατον</span>, «morte»; Jos., Ant. 2, 296: <span class=\"greek\">πληγὴν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Αἰγυπτίοις</span>; cf. também PTebt 331, 10; Just., 39, 2): <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀργήν</span>, <i>punição decorrente da ira</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3:5</a>.</p>\n<p class=\"entry-text\"><b>④ Acrescentar alguma coisa sobre outra: juntar, adicionar.</b> (Aristóteles, Rhet. 3, 6; Fílon, Leg. ad Gai. 125.) Acerca de <i>aflição, dificuldade</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:17</a>, variante de leitura.</p>\n<p class=\"entry-text\"><b>⑤ Apresentar acusações ou imputações: formular, trazer, proferir.</b> (Desde Heródoto 1, 26; também Políbio 5, 41, 3; 38, 18, 2; PRainer 232, 11: <span class=\"greek\">ψευδεῖς</span> <span class=\"greek\">αἰτίας</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">ἐ</span>.; Jos., Ant. 2, 130; 4, 248; 11, 117; Just., D. 9, 1.) <span class=\"greek\">αἰτίαν</span>, <i>acusação</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:18</a>, variante de leitura; <span class=\"greek\">κρίσιν</span> <span class=\"greek\">βλασφημίας</span>, <i>proferir um juízo injurioso</i>, Jd 9. — M-M.</p></section></article>\n<article id=\"entry-epiphrasso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιφράσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiphrássō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέφραξα</span> (ver <span class=\"greek\">φράσσω</span>; Teófilo e outros). <b>Fechar, tapar, obstruir.</b> Por causa do mau cheiro produzido pelo corpo de Judas em decomposição, ninguém podia aproximar-se do lugar de sua morte sem <i>tapar o nariz com as mãos</i>, Pápias 3:3 (cf. Teofrasto, De Sens. 85).</p></section></article>\n<article id=\"entry-epiphoneo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιφωνέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiphōnéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐπεφώνουν</span>; aoristo <span class=\"greek\">ἐπεφώνησα</span>, LXX (ver <span class=\"greek\">φωνέω</span>; Sófocles e outros; inscrições, papiros, LXX; TestJob 43:3; EpArist, Fílon). <b>Clamar, gritar (em voz alta).</b> Com <span class=\"greek\">τινί</span>, <i>contra alguém</i> (cf. Plut., Alex. 665 [3, 6]), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:24</a>; <span class=\"greek\">ἄλλο</span> <span class=\"greek\">τι</span>, <i>algo diferente</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:34</a> (ver <span class=\"greek\">ἄλλος</span> 1c, final). Seguido de discurso direto (OGI 595, 35; PRyl 77, 33; 1 Esdr 9:47), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:21</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:22</a>. — DELG, s.v. <span class=\"greek\">φωνή</span>; M-M.</p></section></article>\n<article id=\"entry-epiphosko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιφώσκω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epiphṓskō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Poeta De Herb. 25; papiros; médio em Jó 41:10, variante.) <b>Aproximar-se o dia ou tornar-se dia; raiar, clarear, amanhecer, talvez avançar ou estar próximo.</b> (PLond I, 130, 39, p. 134 [séculos I/II d.C.]; PGrenf II, 112, 15: <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιφωσκούσῃ</span> <span class=\"greek\">κυριακῇ</span>; Ps.-Clemente, Hom. 3, 1, p. 36, 23 Lag.) <span class=\"greek\">σάββατον</span> <span class=\"greek\">ἐπέφωσκεν</span>, <i>o sábado estava raiando ou se aproximava</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:54</a>; cf. GPt 2:5. <span class=\"greek\">ἐπιφώσκοντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σαββάτου</span>, <i>ao raiar o sábado</i>, GPt 9:34; cf. versículo 35. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιφωσκούσῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μίαν</span> <span class=\"greek\">σαββάτων</span>, <i>quando raiava ou se aproximava o primeiro dia da semana</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:1</a>.</p>\n<p class=\"entry-text\">Ver G. Moore, JAOS 26 (1905), pp. 323–329; C. Turner, JTS 14 (1913), pp. 188–190; F. Burkitt, ibid., pp. 538–546; P. Gardner-Smith, ibid. 27 (1926), pp. 179–181; M. Black, <i>An Aramaic Approach</i>³ (1967), pp. 136–138. Ver ainda <span class=\"greek\">ἐπιφαύσκω</span>. — M-M.</p></section></article>"};
